#!/usr/bin/env bash
# shellcheck disable=SC1087,SC2317,SC2329  # known false positive and unused helpers in the shared wizard library below
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


REPO="vuxng/agenty"
ENVIRONMENT="release"
IDENTITY="Developer ID Application: Vu Nguyen (8WJ6LC5Z59)"
TEAM="8WJ6LC5Z59"
NOTARY_PROFILE="agenty-notary"

# ask_default VAR "Prompt" DEFAULT reads a visible value; Enter takes DEFAULT.
# It goes through the library's ask, which wraps the prompt's colour codes for Readline.
ask_default() {
  local var="$1" prompt="$2" default="$3"
  ask "$var" "$prompt${default:+ [$default]}" || return 1
  [[ -n "${!var}" ]] || printf -v "$var" '%s' "$default"
}

# clean_path undoes what dragging a file into Terminal adds (quotes, escaped
# spaces, trailing space) and expands a leading ~/.
clean_path() {
  local p="$1"
  p="${p%"${p##*[![:space:]]}"}"
  p="${p#"${p%%[![:space:]]*}"}"
  if [[ "$p" == \'*\' || "$p" == \"*\" ]]; then p="${p:1:${#p}-2}"; fi
  p="${p//\\ / }"
  if [[ "$p" == \~/* ]]; then p="$HOME/${p:2}"; fi
  printf '%s' "$p"
}

# ask_file VAR "Prompt" DEFAULT asks until the answer names an existing file.
ask_file() {
  local var="$1" prompt="$2" default="$3" answer path
  while true; do
    ask_default answer "$prompt" "$default"
    path="$(clean_path "$answer")"
    if [[ -f "$path" ]]; then
      printf -v "$var" '%s' "$path"
      return 0
    fi
    warn "No file at: $path"
  done
}

# p12_ok PATH: the password in $P12_PASSWORD opens the file, and it holds the
# team's certificate plus a private key. The password goes through the
# environment, never the command line.
# Matches use `grep ... >/dev/null`, not grep -q: under pipefail, grep -q can quit
# early and the producer then fails with SIGPIPE, turning a match into a failure.
p12_ok() {
  local file="$1"
  P12_PW="$P12_PASSWORD" /usr/bin/openssl pkcs12 -in "$file" -noout -passin env:P12_PW 2>/dev/null || return 1
  P12_PW="$P12_PASSWORD" /usr/bin/openssl pkcs12 -in "$file" -nokeys -clcerts -passin env:P12_PW 2>/dev/null \
    | /usr/bin/openssl x509 -noout -subject 2>/dev/null | grep -F "$TEAM" >/dev/null || return 1
  P12_PW="$P12_PASSWORD" /usr/bin/openssl pkcs12 -in "$file" -nocerts -nodes -passin env:P12_PW 2>/dev/null \
    | grep "PRIVATE KEY" >/dev/null
}

# set_env_secret NAME stores stdin as a secret of the release environment.
# Feed it with `< <(...)`, not a pipe: a pipe runs it in a subshell and the
# summary arrays would lose the result. gh's error, if any, stays visible.
set_env_secret() {
  local name="$1"
  if gh secret set "$name" --env "$ENVIRONMENT" --repo "$REPO" >/dev/null; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s %s secret %s\n' "$GREEN" "$RESET" "$ENVIRONMENT" "$name"
  else
    SKIPPED+=("$ENVIRONMENT secret $name: gh secret set $name --env $ENVIRONMENT --repo $REPO")
    warn "could not set $name"
  fi
}

run_wizard() {

TOTAL_STAGES=7
# Nothing is saved to a .env file: secrets go only to GitHub and the login Keychain.
ENV_FILE=/dev/null

banner "Agenty release signing setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check prerequisites"
say "The Release workflow needs your Developer ID certificate and an App Store"
say "Connect API key to sign and notarize Agenty. This wizard collects both,"
say "checks them, and stores them as secrets of the GitHub environment \"$ENVIRONMENT\"."
printf '\n'
if ! gh auth status >/dev/null 2>&1; then
  warn "gh is not signed in. Run: gh auth login"
  exit 1
fi
step "gh is signed in."
if [[ "$(gh repo view "$REPO" --json visibility --jq .visibility 2>/dev/null)" != "PUBLIC" ]]; then
  warn "$REPO is not public yet. Environments on a private repo need a paid plan."
  confirm "Continue anyway?" || exit 1
else
  step "$REPO is public."
fi
if ! security find-identity -v -p codesigning | grep -F "$IDENTITY" >/dev/null; then
  warn "\"$IDENTITY\" is not in your Keychain."
  exit 1
fi
step "Found \"$IDENTITY\"."
pause "Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Export the Developer ID certificate"
open -a "Keychain Access" >/dev/null 2>&1 || warn "Open Keychain Access yourself (Spotlight: Keychain Access)."
step "In the sidebar choose the login keychain, then the My Certificates tab."
step "Find \"$IDENTITY\" and click its ▸ arrow: a private key must be under it."
step "Right-click the certificate → Export \"$IDENTITY\"…"
step "File Format: Personal Information Exchange (.p12). Save as ~/Downloads/agenty-developer-id.p12"
step "Choose a password for the file. macOS may then ask for your login password."
printf '\n'
while true; do
  ask_file P12_PATH "Path to the .p12:" "$HOME/Downloads/agenty-developer-id.p12"
  ask_secret P12_PASSWORD "Password you set for the .p12:"
  if p12_ok "$P12_PATH"; then
    step "The .p12 opens and holds the team $TEAM certificate with its private key."
    break
  fi
  warn "Could not open the .p12 with that password, or it lacks the $TEAM certificate and key."
  confirm "Use it anyway?" && break
done
pause "Press Enter to continue"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create an App Store Connect API key"
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Sign in with the Apple ID of team $TEAM. If you see Request Access, click it and accept the terms."
step "Open the Team Keys tab and click + (Generate API Key)."
step "Name: Agenty notarization. Access: Developer. Click Generate."
step "Click Download on the new key. Apple allows only one download, so keep a copy somewhere safe."
note "The file is called AuthKey_<KEY ID>.p8."
printf '\n'
default_p8=""
for candidate in "$HOME"/Downloads/AuthKey_*.p8; do
  [[ -f "$candidate" ]] && default_p8="$candidate"
done
while true; do
  ask_file P8_PATH "Path to the .p8:" "$default_p8"
  if head -1 "$P8_PATH" | grep "BEGIN PRIVATE KEY" >/dev/null; then break; fi
  warn "That file is not a .p8 private key."
done
default_key_id="${P8_PATH##*/}"
default_key_id="${default_key_id#AuthKey_}"
default_key_id="${default_key_id%.p8}"
while true; do
  ask_default NOTARY_KEY_ID "Key ID (10 characters, shown in the key's row):" "$default_key_id"
  [[ "$NOTARY_KEY_ID" =~ ^[A-Z0-9]{10}$ ]] && break
  warn "A Key ID is 10 capital letters and digits."
done
step "Copy the Issuer ID shown above the keys table."
while true; do
  ask_default NOTARY_ISSUER_ID "Issuer ID:" ""
  [[ "$NOTARY_ISSUER_ID" =~ ^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$ ]] && break
  warn "An Issuer ID looks like 12345678-abcd-1234-abcd-1234567890ab."
done

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Save a local notarization profile"
say "notarytool checks the key with Apple, then saves it in your login Keychain as"
say "profile \"$NOTARY_PROFILE\", so scripts/build-release.sh can notarize on this Mac."
printf '\n'
if ! xcrun notarytool store-credentials "$NOTARY_PROFILE" \
    --key "$P8_PATH" --key-id "$NOTARY_KEY_ID" --issuer "$NOTARY_ISSUER_ID"; then
  warn "Apple did not accept the key. Check the Key ID and Issuer ID, then run the wizard again."
  exit 1
fi
pause "Press Enter to continue"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Create the GitHub environment \"$ENVIRONMENT\""
say "Only the stable branch may use this environment, so pull requests never see its secrets."
printf '\n'
confirm "Create or update environment \"$ENVIRONMENT\" on $REPO?" || exit 1
gh api --method PUT "repos/$REPO/environments/$ENVIRONMENT" --input - >/dev/null \
  <<< '{"deployment_branch_policy":{"protected_branches":false,"custom_branch_policies":true}}'
policies="$(gh api "repos/$REPO/environments/$ENVIRONMENT/deployment-branch-policies" --jq '[.branch_policies[].name] | join(",")')"
if [[ ",$policies," != *",stable,"* ]]; then
  gh api --method POST "repos/$REPO/environments/$ENVIRONMENT/deployment-branch-policies" \
    -f name=stable -f type=branch >/dev/null
fi
step "Environment \"$ENVIRONMENT\" accepts deployments from stable only."
pause "Press Enter to continue"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Upload the secrets"
say "Values go to gh through stdin; nothing is printed."
printf '\n'
confirm "Upload 5 secrets to environment \"$ENVIRONMENT\"?" || exit 1
set_env_secret DEVELOPER_ID_P12_BASE64 < <(base64 -i "$P12_PATH")
set_env_secret DEVELOPER_ID_P12_PASSWORD < <(printf '%s' "$P12_PASSWORD")
set_env_secret NOTARY_KEY_P8_BASE64 < <(base64 -i "$P8_PATH")
set_env_secret NOTARY_KEY_ID < <(printf '%s' "$NOTARY_KEY_ID")
set_env_secret NOTARY_ISSUER_ID < <(printf '%s' "$NOTARY_ISSUER_ID")
pause "Press Enter to continue"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Clean up the exported files"
say "GitHub and your login Keychain now hold what the release needs."
step "If you want a backup, store the .p12 (with its password) and the .p8 in your password manager."
step "Then delete both files:"
note "  $P12_PATH"
note "  $P8_PATH"
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
